import { PictureProps } from './Picture.types';

// Keep in sync with IMAGE_WIDTHS in scripts/optimize-media.mjs.
const IMAGE_WIDTHS = [480, 960];

const getSrcSet = (src: string, format: 'avif' | 'webp') => {
  const base = src.replace(/\.[^.]+$/, '');

  return IMAGE_WIDTHS.map(
    (width) => `${base}-${width}.${format} ${width}w`,
  ).join(', ');
};

/**
 * Serves AVIF/WebP variants generated by `npm run optimize:media`, falling
 * back to the original JPEG. Lazy-loads unless `priority` is set.
 */
export const Picture = ({
  src,
  sizes,
  alt = '',
  priority = false,
  className,
  ...imgProps
}: PictureProps) => (
  // `display: contents` lets the <img> be styled as if it were the direct
  // child of the surrounding layout.
  <picture style={{ display: 'contents' }}>
    <source type="image/avif" srcSet={getSrcSet(src, 'avif')} sizes={sizes} />
    <source type="image/webp" srcSet={getSrcSet(src, 'webp')} sizes={sizes} />
    <img
      src={src}
      alt={alt}
      className={className}
      loading={priority ? 'eager' : 'lazy'}
      decoding={priority ? 'auto' : 'async'}
      // React 18 doesn't know the camelCase prop yet; pass the raw attribute.
      {...{ fetchpriority: priority ? 'high' : 'auto' }}
      {...imgProps}
    />
  </picture>
);
